"""Exact cache-budgeted IPv6 forwarding image compiler."""
import json
import sys

import native
from protocol import Invalid, MAX_INPUT, parse_request

U = 1 << 128
U_HEX = "1" + "0" * 32


def canonical_runs(routes):
    """Compile a normalized route map into unique maximal LPM runs."""
    events = []
    for (start, length), hop in routes.items():
        events.append((start, 1, length, hop))  # starts after ends
        if length:
            end = start + (1 << (128 - length))
            events.append((end, 0, length, hop))
    events.sort()

    active = {}  # active prefix length -> hop; active prefixes form a chain
    starts = []
    hops = []
    cursor = 0

    def emit(end):
        nonlocal cursor
        if end <= cursor:
            cursor = end
            return
        hop = active[max(active)] if active else None
        if not hops or hops[-1] != hop:
            starts.append(cursor)
            hops.append(hop)
        cursor = end

    i = 0
    n = len(events)
    while i < n:
        x = events[i][0]
        emit(x)
        # At one boundary every ending interval is removed before new ones
        # become active.  events was sorted with end type 0 before start 1.
        while i < n and events[i][0] == x:
            _, typ, length, hop = events[i]
            if typ == 0:
                active.pop(length, None)
            else:
                active[length] = hop
            i += 1
        cursor = x
    emit(U)
    return starts, hops


def forwarding_changes(old, new):
    old_starts, old_hops = old
    new_starts, new_hops = new
    i = j = 0
    pos = 0
    rows = []
    while pos < U:
        old_end = old_starts[i + 1] if i + 1 < len(old_starts) else U
        new_end = new_starts[j + 1] if j + 1 < len(new_starts) else U
        end = min(old_end, new_end)
        old_hop = old_hops[i]
        new_hop = new_hops[j]
        if old_hop != new_hop:
            if (rows and rows[-1][1] == pos and rows[-1][2] == old_hop
                    and rows[-1][3] == new_hop):
                rows[-1][1] = end
            else:
                rows.append([pos, end, old_hop, new_hop])
        pos = end
        if end == old_end:
            i += 1
        if end == new_end:
            j += 1
    return [[U_HEX if a == U else f"{a:032x}",
             U_HEX if b == U else f"{b:032x}", oh, nh]
            for a, b, oh, nh in rows]


def compile_case(case):
    routes = {}
    for (start, length), hop in case["initial"]:
        routes[(start, length)] = hop
    versions = [canonical_runs(routes)]
    for transaction in case["transactions"]:
        for op, route, hop in transaction:
            if op == "set":
                routes[route] = hop
            else:
                routes.pop(route, None)
        versions.append(canonical_runs(routes))

    changes = []
    for v in range(len(versions) - 1):
        changes.append(forwarding_changes(versions[v], versions[v + 1]))
    return versions, changes


def compile_request(cases):
    compiled = []
    total_runs = 0
    for case in cases:
        versions, changes = compile_case(case)
        for starts, _hops in versions:
            r = len(starts)
            if r > 64:
                raise Invalid("version run budget")
            total_runs += r
            if total_runs > 128:
                raise Invalid("global run budget")
        compiled.append((case, versions, changes))

    if not compiled:
        return {"cases": []}

    plan = ["PLAN " + str(len(compiled))]
    for case, versions, _changes in compiled:
        hit, miss, dec = case["costs"]
        bursts = case["bursts"]
        plan.append(" ".join(map(str, [
            case["cache_pages"], hit, miss, dec[0], dec[1], dec[2],
            len(versions), len(bursts)
        ])))
        for starts, hops in versions:
            plan.append(str(len(starts)))
            for start, hop in zip(starts, hops):
                plan.append(f"{start:032x} {-1 if hop is None else hop}")
        for version, repeat, addresses in bursts:
            row = f"{version} {repeat} {len(addresses)}"
            if addresses:
                row += " " + " ".join(f"{a:032x}" for a in addresses)
            plan.append(row)

    lines = native.run(plan)
    at = 0
    results = []
    for case, versions, changes in compiled:
        images = []
        for _ in versions:
            if at >= len(lines):
                raise RuntimeError("short PLAN image output")
            images.append(lines[at].strip())
            at += 1

        burst_answers = []
        for _version, _repeat, addresses in case["bursts"]:
            if at >= len(lines):
                raise RuntimeError("short PLAN burst output")
            count = int(lines[at])
            at += 1
            if count != len(addresses):
                raise RuntimeError("PLAN answer count")
            answers = []
            for _ in range(count):
                if at >= len(lines):
                    raise RuntimeError("short PLAN answer output")
                fields = list(map(int, lines[at].split()))
                at += 1
                if len(fields) < 3:
                    raise RuntimeError("PLAN answer framing")
                hop, run, path_len = fields[0], fields[1], fields[2]
                path = fields[3:]
                if path_len != len(path):
                    raise RuntimeError("PLAN path framing")
                answers.append([None if hop == -1 else hop, run, path])
            burst_answers.append(answers)

        if at >= len(lines):
            raise RuntimeError("short PLAN objective")
        objective = list(map(int, lines[at].split()))
        at += 1
        if len(objective) != 2:
            raise RuntimeError("PLAN objective framing")

        version_rows = []
        for (starts, hops), image in zip(versions, images):
            version_rows.append({
                "starts": [f"{x:032x}" for x in starts],
                "hops": [None if h is None else h for h in hops],
                "image": image,
            })
        results.append({
            "versions": version_rows,
            "changes": changes,
            "bursts": burst_answers,
            "objective": objective,
        })

    if at != len(lines):
        raise RuntimeError("extra PLAN output")
    return {"cases": results}


def main():
    try:
        cases = parse_request(sys.stdin.buffer.read(MAX_INPUT + 1))
        result = compile_request(cases)
    except Invalid:
        result = {"error": "invalid"}
    json.dump(result, sys.stdout, separators=(",", ":"), allow_nan=False)
    sys.stdout.write("\n")


if __name__ == "__main__":
    main()
